    # Validate day string
    try:
        dt = datetime.strptime(day, "%Y-%m-%d")
    except ValueError:
        raise ValueError("Invalid day string")

    # 15-min granularity
    GRANULARITY = 15

    # Working hours
    weekday = dt.weekday()  # Monday=0, Friday=4
    work_start = 9*60
    work_end = 17*60

    # Friday cutoff
    FRIDAY_CUTOFF = 15*60  # 15:00 in minutes

